-- Prompt 5: durable workspace-scoped automation engine.
create type public.automation_recipe as enum ('INSTAGRAM_COMMENT_TO_DM','INSTAGRAM_INBOUND_DM','WHATSAPP_INBOUND');
create type public.automation_lifecycle as enum ('DRAFT','NEEDS_SETUP','READY_TO_TEST','TEST_FAILED','READY','ACTIVE','PAUSED','NEEDS_REAUTH','NEEDS_APPROVAL','ERROR','ARCHIVED');
create type public.automation_run_state as enum ('NEW','WELCOME_SENT','COLLECTING_FIELDS','WAITING_FOR_MEDIA','QUALIFIED','COMPLETED','HUMAN_REVIEW','OPTED_OUT','WINDOW_CLOSED','FAILED');
create table public.campaign_sources(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,channel text not null,provider_source_id text,source_type text not null,created_at timestamptz not null default now(),unique(workspace_id,id));
create table public.automations(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,recipe public.automation_recipe not null,status public.automation_lifecycle not null default 'DRAFT',active_version_id uuid,paused_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,id));
create table public.automation_versions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,automation_id uuid not null,version integer not null,configuration jsonb not null,content_hash text not null,created_at timestamptz not null default now(),unique(workspace_id,automation_id,version),unique(workspace_id,id),foreign key(workspace_id,automation_id) references public.automations(workspace_id,id) on delete cascade);
alter table public.automations add constraint automations_active_version_fk foreign key(workspace_id,active_version_id) references public.automation_versions(workspace_id,id);
create table public.automation_triggers(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,automation_version_id uuid not null,kind text not null,configuration jsonb not null default '{}',foreign key(workspace_id,automation_version_id) references public.automation_versions(workspace_id,id) on delete cascade);
create table public.automation_questions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,automation_version_id uuid not null,field_key text not null,prompt text not null,position integer not null,required boolean not null default true,validation jsonb not null default '{}',skip_rule jsonb not null default '{}',unique(workspace_id,automation_version_id,field_key),foreign key(workspace_id,automation_version_id) references public.automation_versions(workspace_id,id) on delete cascade);
create table public.automation_rules(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,automation_version_id uuid not null,rule_type text not null,configuration jsonb not null default '{}',foreign key(workspace_id,automation_version_id) references public.automation_versions(workspace_id,id) on delete cascade);
create table public.automation_message_steps(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,automation_version_id uuid not null,step_key text not null,position integer not null,body text not null,message_type text not null default 'free_form',unique(workspace_id,automation_version_id,step_key),foreign key(workspace_id,automation_version_id) references public.automation_versions(workspace_id,id) on delete cascade);
create table public.service_windows(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,conversation_id uuid not null,channel text not null,opened_at timestamptz not null,expires_at timestamptz not null,source_provider_event_id text not null,policy_state text not null default 'open',updated_at timestamptz not null default now(),unique(workspace_id,conversation_id,channel));
create table public.automation_runs(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,automation_id uuid not null,automation_version_id uuid not null,conversation_id uuid not null,state public.automation_run_state not null default 'NEW',collected_fields jsonb not null default '{}',media_count integer not null default 0,last_provider_event_id text,human_paused boolean not null default false,failure_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,automation_id,conversation_id),unique(workspace_id,id),foreign key(workspace_id,automation_id) references public.automations(workspace_id,id),foreign key(workspace_id,automation_version_id) references public.automation_versions(workspace_id,id));
create table public.automation_run_steps(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,run_id uuid not null,step_key text not null,status text not null,attempt integer not null default 1,available_at timestamptz not null default now(),completed_at timestamptz,error_code text,foreign key(workspace_id,run_id) references public.automation_runs(workspace_id,id) on delete cascade);
create table public.outbound_attempts(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,run_id uuid not null,idempotency_key text not null,channel text not null,recipient_ref text not null,message_type text not null,status text not null,provider_message_id text,error_code text,created_at timestamptz not null default now(),unique(workspace_id,idempotency_key),foreign key(workspace_id,run_id) references public.automation_runs(workspace_id,id) on delete cascade);
create table public.automation_idempotency_keys(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,key text not null,scope text not null,status text not null default 'reserved',created_at timestamptz not null default now(),unique(workspace_id,key));
create table public.automation_dead_letters(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,run_id uuid not null,run_step_id uuid,error_code text not null,safe_summary text not null,recoverable boolean not null default true,recovered_at timestamptz,created_at timestamptz not null default now(),foreign key(workspace_id,run_id) references public.automation_runs(workspace_id,id) on delete cascade);
create table public.human_takeovers(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,conversation_id uuid not null,run_id uuid,actor_id uuid references auth.users(id) on delete set null,reason text not null,status text not null default 'active',started_at timestamptz not null default now(),resumed_at timestamptz);
create table public.automation_audit_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,event_type text not null,automation_id uuid,run_id uuid,actor_id uuid references auth.users(id) on delete set null,safe_details jsonb not null default '{}',created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['campaign_sources','automations','automation_versions','automation_triggers','automation_questions','automation_rules','automation_message_steps','service_windows','automation_runs','automation_run_steps','outbound_attempts','automation_idempotency_keys','automation_dead_letters','human_takeovers','automation_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant all on public.%I to service_role',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy %I on public.%I for select to authenticated using(private.is_active_member(workspace_id))',t||'_select_member',t);end loop;end $$;
